import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.JigsawStructureData{StructureData: map[string]any{}}
EMPTY = bytes.fromhex("0a0000")

GOLDENS = [
    pytest.param(v2225.JigsawStructureDataPacket(jigsaw_structure_data_tag=v2225.nbt.CompoundTag()), EMPTY, id="empty"),
]


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_jigsaw_structure_data_is_packet_313(version):
    assert version.PACKETS[313] is version.JigsawStructureDataPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_jigsaw_structure_data_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_jigsaw_structure_data_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_a_populated_jigsaw_tag_carries_its_entries():
    packet = v2225.JigsawStructureDataPacket(
        jigsaw_structure_data_tag=v2225.nbt.CompoundTag({"size": v2225.nbt.IntTag(3)})
    )
    assert v2225.JigsawStructureDataPacket.from_bytes(bytes(packet)) == packet
